#ifndef INSTRUCTION_HPP
#define INSTRUCTION_HPP

#include <string>

enum class Type { R, I, S, B, U, J };
typedef unsigned int Instruction;
typedef unsigned int Immediate;
typedef int SImmediate;
class InvalidAccess {
public:
    InvalidAccess() {}
};
class InstructionBase {
public:
    unsigned opcode;
    unsigned rs1;
    unsigned rs2;
    unsigned rd;
    unsigned funct3;
    unsigned funct7;
    Immediate imm;
    Instruction inst;
    Type t;

    static constexpr unsigned int bin_mask(int digits) {
        return (1 << digits) - 1;
    }

    static unsigned int get_digits(unsigned int n, int hi, int lo) {
        return (n >> lo) & bin_mask(hi - lo + 1);
    }

    static unsigned int expand_digit(unsigned int digit, int lo) {
        return digit ? (0xffffffff << lo) : 0;
    }

    bool is_valid(const std::string &key) {
        // Implementation based on key and instruction type
        return true; // Placeholder implementation
    }

    void verify(const std::string &key) {
        if (!is_valid(key)) {
            throw InvalidAccess();
        }
    }

    void debug() {
        switch (opcode) {
            case 0x0010011: // Example opcode for debugging
                std::cout << "ADDI" << std::endl;
                break;
            default:
                std::cout << "Unknown Instruction" << std::endl;
        }
    }

    bool has_op1() {
        return t != Type::U && t != Type::J;
    }

    bool has_op2() {
        return t == Type::R || t == Type::S || t == Type::B;
    }
};
class InstructionR : public InstructionBase {
public:
    InstructionR(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        funct7 = get_digits(inst, 31, 25);
    }
};
class InstructionI : public InstructionBase {
public:
    InstructionI(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        imm = expand_digit(get_digits(inst, 31, 20), 20);
    }
};
class InstructionS : public InstructionBase {
public:
    InstructionS(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        imm = expand_digit(get_digits(inst, 7, 7) << 5 | get_digits(inst, 11, 8) << 1 | get_digits(inst, 31, 25) << 6 | get_digits(inst, 14, 12), 5);
    }
};
class InstructionB : public InstructionBase {
public:
    InstructionB(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        imm = expand_digit(get_digits(inst, 7, 7) << 11 | get_digits(inst, 30, 25) << 6 | get_digits(inst, 11, 8) << 1 | get_digits(inst, 31, 31) << 12, 11);
    }
};
class InstructionU : public InstructionBase {
public:
    InstructionU(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = expand_digit(get_digits(inst, 31, 12), 12);
    }
};
class InstructionJ : public InstructionBase {
public:
    InstructionJ(const Instruction &inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = expand_digit(get_digits(inst, 31, 20) << 1 | get_digits(inst, 19, 12) << 12 | get_digits(inst, 20, 20) << 11 | get_digits(inst, 30, 21) << 1, 1);
    }
};

#endif // INSTRUCTION_HPP
